#include<bits/stdc++.h>
using namespace std;
struct linex{
	int v;
	int w;
	int nxt;
	int c;
};
int head[210],cnt,cpos[210],vis[210],qvis[210],totc,dis[210],inf=1000000000;
linex l[21000];
queue<int>que;
void add(int u,int v,int w,int c){
	l[cnt].nxt=head[u];
	head[u]=cnt;
	l[cnt].v=v;
	l[cnt].w=w;
	l[cnt].c=c;
	cnt++;
	l[cnt].nxt=head[v];
	head[v]=cnt;
	l[cnt].v=u;
	l[cnt].w=0;
	l[cnt].c=-c;
	cnt++;
}
int spfa(int st,int en,int n){
	int i,j,t;
	for(i=0;i<n;i++)
	{
		vis[i]=0;
		dis[i]=inf;
		cpos[i]=head[i];
	}
	que.push(st);
	dis[st]=0;
	vis[st]=1;
	qvis[st]=1;
	while(!que.empty())
	{
		t=que.front();
		que.pop();
		qvis[t]=0;
		for(j=head[t];j!=-1;j=l[j].nxt)
		{
			if(l[j].w>0&&dis[l[j].v]>dis[t]+l[j].c)
			{
				dis[l[j].v]=dis[t]+l[j].c;
				vis[l[j].v]=1;
				if(!qvis[l[j].v])
				{
					que.push(l[j].v);
					qvis[l[j].v]=1;
				}
			}
		}
	}
	return vis[en];
}
long long dfs(int p,int en,int curr){
	int x,j,flow=0;
	if(p==en)return curr;
	for(j=cpos[p];j!=-1&&flow<curr;j=l[j].nxt)
	{
		cpos[p]=j;
		qvis[p]=1;
		if(l[j].w>0&&dis[l[j].v]==dis[p]+l[j].c&&!qvis[l[j].v])
		{
			x=dfs(l[j].v,en,min(curr-flow,l[j].w));
			flow+=x;
			l[j].w-=x;
			l[j^1].w+=x;
			totc+=l[j].c*x;
		}
		qvis[p]=0;
	}
	return flow;
}
