								cmsk|=(1<<p);
								dp[l][r][cmsk]=(dp[l][r][cmsk]+dp[l][i][j]*sgvl[i][r][t][p+1])%mod;
							}
						}
					}
				}
				for(j=1;j<(1<<n);j++)
				{
					for(i=0;(j>>i&1^1);i++);
					for(t=n-1;(j>>t&1^1);t--);
					sgvl[l][r][i][t+1]=(sgvl[l][r][i][t+1]+mod-dp[l][r][j])%mod;
				}
				for(i=0;i<n;i++)
				{
					cmsk=0;
					for(t=i;t<n;t++)
					{
						cmsk|=(1<<t);
						dp[l][r][cmsk]=(dp[l][r][cmsk]+sgvl[l][r][i][t+1])%mod;
					}
				}
				if(len==1)continue;
				for(j=0;j<(1<<n);j++)dp[l][r][j]=(dp[l][r-1][j]+dp[l][r][j])%mod;
			}
		}
		for(i=0;i<=n;i++)
		{
			for(j=0;j<(1<<n);j++)
			{
				dp2[i][j]=0;
