						for(t=i;t<n&&(j>>t&1^1);t++)
						{
							cmsk|=(1<<t);
							dp2[r][cmsk]=(dp2[r][cmsk]+dp2[l][j]*sgvl[l][r][i][t+1])%mod;
							dpvl2[r][cmsk]=(dpvl2[r][cmsk]+(dp2[l][j]+dpvl2[l][j])*sgvl[l][r][i][t+1])%mod;
						}
					}
				}
			}
		}
		ans=0;
		for(j=1;j<(1<<n);j++)ans=(ans+dpvl2[n][j])%mod;
		cout<<ans<<'\n';
	}
	return 0;
}
